css:
 .widget-container {
  font-size: 16px;
  width: min(600px, 94%);
  margin-inline: auto;
  line-height: 1.35;
}

 .article-body *,
 .widget-container * {
  box-sizing: border-box;
}

 .filter-table>*+* {
  margin-top: 1em;
}

 .filter-table-title {
  background-color: #f09f4d;
  text-align: center;
  color: #fff;
  padding: 1em 0;
  font-size: 1.25em;
  font-weight: 600;
  position: relative;
}

 .filter-table-title::before,
 .filter-table-title::after {
  content: "";
  width: 100%;
  height: 2px;
  background-color: #04384c;
  display: block;
  position: absolute;
  left: 0;
}

 .filter-table-title::before {
  top: -4px;
}

 .filter-table-title::after {
  bottom: -4px;
}

 .filter-table-description {
  font-size: 0.875em;
  color: #666;
}

 .filter-table-content .title {
  text-align: center;
  font-weight: 600;
  width: fit-content;
  margin-inline: auto;
  padding-inline: 1em;
  background: linear-gradient(transparent 64%, #ffddbc 0%);
  margin-bottom: 1em;
}

 .filter-table-content .filter-tag {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5em;
  font-size: 0.875em;
}

 .filter-table-content .filter-tag-item input {
  display: none;
}

 .filter-table-content .filter-tag-item input+label {
  display: block;
  background-color: #4288c6;
  color: #fff;
  padding: 0.5em 1em;
  border-radius: 0.5em;
  cursor: pointer;
  transition: background-color 0.3s;
}

 .filter-table-content .filter-tag-item input:checked+label {
  background-color: #f43254;
}

 .filter-table-wrapper .guide-text {
  text-align: right;
  font-size: 0.75em;
  color: #666;
  margin-bottom: 1em;
  animation: float-text 1s infinite alternate;
}

 .filter-table-wrapper .overflow-scroll {
  overflow: auto;
  max-height: var(--max-height, 500px);
  border-left: solid 1px #ccc;
}

@media (max-width: 500px) {
   .filter-table-wrapper .overflow-scroll {
    max-height: var(--sp-max-height, 500px);
  }
}

 .filter-table-wrapper table {
  width: max-content;
  border-collapse: collapse;
  border-spacing: 0;
  border-top: solid 1px #ccc;
  border-bottom: solid 1px #ccc;
}

 .filter-table-wrapper table thead {
  background-color: #63a84d;
  position: sticky;
  top: 0;
  z-index: 1;
}

 .filter-table-wrapper table thead th {
  color: #fff;
  padding: 0.75em 1em;
}

 .filter-table-wrapper table thead th:first-child {
  position: sticky;
  left: 0;
  z-index: 2;
  background-color: #63a84d;
}

 .filter-table-wrapper table thead th:not(:first-child) {
  border-left: solid 1px #ddd;
}

 .filter-table-wrapper table tbody {
  position: relative;
  z-index: 0;
}

 .filter-table-wrapper table tbody tr:not(:last-child) {
  border-bottom: solid 1px #ddd;
}

 .filter-table-wrapper table tbody tr td:not(:first-child) {
  border-left: solid 1px #ddd;
}

 .filter-table-wrapper table tbody td {
  padding: 0.5em 0.75em;
  font-size: 0.875em;
}

 .filter-table-wrapper table tbody td:first-child {
  position: sticky;
  left: 0;
  z-index: 1;
  background-color: #f1f9ee;
}

 .filter-table-wrapper table tbody td.thumbnail {
  text-align: center;
}

 .filter-table-wrapper table tbody td.thumbnail img {
  width: 100px;
  margin-inline: auto;
}

 .filter-table-wrapper table tbody td.thumbnail .label {
  font-size: 0.875em;
  font-weight: 600;
  margin-top: 0.5em;
}

@-moz-keyframes float-text {
  0% {
    transform: translateX(5px);
  }

  100% {
    transform: translateX(-5px);
  }
}

@-webkit-keyframes float-text {
  0% {
    transform: translateX(5px);
  }

  100% {
    transform: translateX(-5px);
  }
}

@-o-keyframes float-text {
  0% {
    transform: translateX(5px);
  }

  100% {
    transform: translateX(-5px);
  }
}

@keyframes float-text {
  0% {
    transform: translateX(5px);
  }

  100% {
    transform: translateX(-5px);
  }
}

.itemIntroduct__area {
  width: 100%;
  max-width: 400px;
  height: auto;
  margin: 0 auto;
  font-size: min(3vw, 16px);
  border: 1px solid #4B9DA9;
}

.itemIntroduct__area,
.itemIntroduct__area * {
  box-sizing: border-box;
}

.itemIntroduct__area p {
  margin: 0;
}

.itemIntroduct__area img {
  width: 100%;
  height: auto;
}

.itemIntroduct--head__box {
  width: 100%;
  height: auto;
  background-color: #4B9DA9;
  padding: 0.5em 0;
}

.itemIntroduct--head__box .head {
  color: #fff;
  font-weight: bold;
  font-size: 1.2em;
  text-align: center;
}

.itemIntroduct--inner__box {
  width: 100%;
  height: auto;
  padding: 1em;
  background-color: #f2f0c7;
}

.itemIntroduct--flex__box {
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  column-gap: 0.5em;
}

.itemIntroduct--img__box {
  width: 80%;
  height: auto;
}

.itemIntroduct--detail__box .itemName {
  color: #ba5f2a;
  text-decoration: underline;
  font-size: 1em;
  font-weight: bold;
}

.itemIntroduct--detail__box .text {
  font-size: 0.8em;
  color: #333;
}

.itemIntroduct--inner__box .btnLink {
  width: 100%;
  height: auto;
  border-radius: 10vw;
  padding: 0.6em 0;
  margin-top: 1em;
  background-color: #91C6BC;
  box-shadow: 0 3px 0 #4B9DA9;
  color: #fff;
  font-weight: bold;
  text-align: center;
  text-decoration: none;
  display: block;
  transform: translateY(0);
  transition: transform 0.2s, box-shadow 0.2s;
  position: relative;
}

.itemIntroduct--inner__box .btnLink:after {
  content: '';
  width: 0.4em;
  height: 0.4em;
  display: block;
  border-color: #fff;
  border-style: solid;
  border-width: 0 1px 1px 0;
  transform: rotate(-45deg) translateY(-50%);
  position: absolute;
  top: 50%;
  right: 8em;
}

.itemIntroduct--inner__box .btnLink:hover {
  box-shadow: 0 0px 0 #4B9DA9;
  transform: translateY(3px);
  transition: transform 0.2s, box-shadow 0.2s;
}

.rankingInfo__table {
  width: 100%;
  height: auto;
  border: 2px solid #2B3467;
  font-size: min(2.5vw, 14px);
  color: #333;
  border-collapse: collapse;
}

.rankingInfo__table,
.rankingInfo__table * {
  box-sizing: border-box;
}

.rankingInfo__table img {
  width: 100%;
  height: auto;
}

.rankingInfo__table p {
  margin: 0;
}

.rankingInfo__table tr.thead th {
  width: 9%;
  height: auto;
  text-align: center;
  background: #FCFFE7;
  padding: 1.5em 0.5em;
  border-width: 0 1px 1px 0;
  border-color: #2B3467;
  border-style: solid;
}

.rankingInfo__table tr.thead th:first-of-type,
.rankingInfo__table tr.thead th:nth-of-type(2),
.rankingInfo__table tr.thead th:last-of-type {
  width: 12%;
}

.rankingInfo__table tr.thead th:last-of-type {
  border-width: 0 0 1px 0;
}

.rankingInfo__table tbody tr th,
.rankingInfo__table tbody tr td {
  padding: 0.5em 0.2em;
  text-align: center;
  border-width: 0 1px 1px 0;
  border-color: #2B3467;
  border-style: solid;
  vertical-align: middle;
}

.rankingInfo__table tbody tr td {
  height: 8em;
}

.rankingInfo__table tbody tr:last-of-type th,
.rankingInfo__table tbody tr:last-of-type td {
  border-width: 0 1px 0 0;
}

.rankingInfo__table tbody tr td .star {
  width: 100%;
  position: relative;
}

.rankingInfo__table .star .starNum {
  color: #EB455F;
  font-size: 1.2em;
  font-weight: bold;
}

.starWrap {
  position: relative;
  display: inline-block;
  width: 5.1em;
  font-size: 1em;
  line-height: 1;
}

.starBg {
  color: #EB455F;
  font-size: 1.25em;
}

.starFill {
  color: #EB455F;
  position: absolute;
  top: 0.18em;
  left: 0;
  white-space: nowrap;
  overflow: hidden;
  width: calc((attr(data-num number) / 5) * 100%);
}

.starWrap .starFill {
  width: calc((attr(data-num number) / 5) * 100%);
}

.rankingInfo__table tbody tr td:last-of-type {
  border-width: 0 0 1px 0;
}

.rankingInfo__table .detailBtn {
  width: 100%;
  height: auto;
  display: block;
  background-color: #EB455F;
  border-radius: 3px;
  border-bottom: 3px solid #c0384c;
  color: #fff;
  text-decoration: none;
  font-size: 0.95em;
  padding: 0.3em 0;
  margin-top: 0.5em;
  font-weight: normal;
  display: block;
}

.rankingInfo__table .grayBtn {
  width: 100%;
  height: auto;
  display: block;
  background-color: #aaa;
  border-radius: 3px;
  border-bottom: 3px solid #999;
  color: #fff;
  text-decoration: none;
  font-size: 0.95em;
  padding: 0.3em 0;
  font-weight: normal;
  display: block;
}

.rankingInfo__table tbody tr td {
  font-size: 0.9em;
}

.rankingInfo__table tbody tr td .eval:before {
  content: attr(data-eval);
  display: inline-block;
  text-align: center;
  font-size: 3em;
  font-weight: bold;
  line-height: 1;
}

.rankingInfo__table tbody tr td .eval[data-eval="◎"]:before {
  color: #EB455F;
}

.rankingInfo__table tbody tr td .eval[data-eval="○"]:before {
  color: #e49abe;
}

.rankingInfo__table tbody tr td .eval[data-eval="△"]:before {
  color: #61ba6b;
}

.rankingInfo__table tbody tr td .eval[data-eval="×"]:before {
  color: #6382f1;
  font-size: 3.5em;
}

@media screen and (max-width: 600px) {
  .rankingInfo__wrap {
    width: 100%;
    height: auto;
    overflow-x: scroll;
    padding-bottom: 1em;
  }

  .rankingInfo__table {
    width: 200%;
  }
}

 .widget-container {
  font-size: 16px;
  width: min(100%, 750px);
  margin-inline: auto;
  line-height: 1.35;
}

@media (max-width: 500px) {
   .widget-container {
    font-size: 3.3vw;
  }
}

 .rank-column {
  display: grid;
  grid-template-columns: repeat(3, calc(100% / 3 - 1em));
  gap: 1em;
}

 .rank-column-item {
  display: grid;
  gap: 0.5em;
  place-items: center;
}

 .rank-column-item .clown {
  width: min(25%, 75px);
}

 .rank-column-item .clown img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

 .rank-column-item .copy {
  font-size: 1em;
  text-align: center;
}

 .rank-column-item .baloon {
  width: fit-content;
  margin-inline: auto;
  background-color: #389ddc;
  color: #fff;
  padding: 0.5em 1em;
  border-radius: 99px;
  line-height: 1;
  position: relative;
}

 .rank-column-item .baloon::before {
  content: "";
  position: absolute;
  bottom: -0.35em;
  left: 50%;
  translate: -50% 0;
  width: 1em;
  aspect-ratio: 2/1;
  background-color: #389ddc;
  clip-path: polygon(100% 0, 0 0, 51% 100%);
}

 .rank-column-item .btn {
  position: relative;
  width: 100%;
  text-decoration: none;
  display: block;
  overflow: hidden;
  border-radius: 99px;
}

 .rank-column-item .btn::after {
  content: '';
  position: absolute;
  top: -100px;
  left: -100px;
  width: 50px;
  height: 50px;
  background-image: linear-gradient(100deg, rgba(255, 255, 255, 0) 10%, #fff 100%, rgba(255, 255, 255, 0) 0%);
  animation: shiny 4s infinite;
  pointer-events: none;
  z-index: 2;
}

 .rank-column-item .btn .btn-text {
  width: 100%;
  text-align: center;
  background-color: #fd5925;
  color: #fff;
  padding: 0.75em 1em;
  border-radius: 99px;
  line-height: 1;
  text-decoration: none;
  position: relative;
  z-index: 1;
  animation: click_or 3s infinite;
  border-bottom: 4px solid #ca471d;
  font-weight: 600;
}

 * {
  box-sizing: border-box;
}

img {
width:100%;
height:auto;
}

@keyframes click_or {
  0% {
    translate: 0 0;
  }

  10% {
    translate: 0 3px;
  }

  15% {
    translate: 0 0;
  }

  25% {
    translate: 0 3px;
  }

  35% {
    translate: 0 0;
  }
}

@keyframes shiny {
  0% {
    transform: scale(0) rotate(25deg);
    opacity: 0;
  }

  50% {
    transform: scale(1) rotate(25deg);
    opacity: 1;
  }

  100% {
    transform: scale(50) rotate(25deg);
    opacity: 0;
  }
}

 .bg-wrap {
  width: 100%;
  max-width: 800px;
  margin: 0 auto;
  background-color: #ededed;
  border-radius: 30px;
  padding: min(5%, 45px);
  display: flex;
  flex-direction: column;
  overflow: auto;
  box-sizing: border-box;
}

 .icon-link-list {
  margin: 0 auto;
  padding: 0;
  list-style: none;
  display: grid;
  grid-template-columns: repeat(4, 22.5%);
  gap: 10px;
}

 .icon-link-list>li a {
  text-decoration: none;
}

 .icon-link-item {
  width: 76px;
  height: 76px;
  padding-top: 3px;
  background-color: #ffffff;
  border-radius: 8px;
  box-shadow: rgba(0, 0, 0, 0.16) 0px 1px 4px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 3px;
  text-align: center;
  box-sizing: border-box;
}

 .icon piuture,
 .icon img,
 .icon video {
  width: 45px;
  height: auto;
  margin: 0 !important;
  vertical-align: bottom;
  display: inline !important;
}

 .icon-link-item .title {
  color: #363a45;
  font-size: 11px;
  padding: 0px 5px;
  line-height: 1.2;
  box-sizing: border-box;
}

.accordionMap__area {
  position: relative;
  overflow: hidden;
  width: 100%;
  margin: 0 auto;
  color: #B17F59;
  font-size: 16px;
}

@media screen and (max-width: 600px) {
  .accordionMap__area {
    font-size: 12px;
  }
}

.accordionMap__area input {
  display: none;
}

.accordionMap__area label {
  font-weight: bold;
  display: block;
  cursor: pointer;
  background: #B17F59;
  color: #fff;
  text-align: center;
  font-size: 1.5em;
  padding: 0.5em;
  position: relative;
  transition: background-color 0.2s;
}

.accordionMap__area input:checked+label {
  background: #8e6647;
}

.accordionMap__area input[type=checkbox]+label::after {
  content: '';
  position: absolute;
  top: 45%;
  right: 2em;
  margin-left: 1em;
  display: block;
  width: 0.4em;
  height: 0.4em !important;
  border-width: 0 2px 2px 0;
  border-color: #fff;
  border-style: solid;
  transform: translateY(-50%) rotate(45deg);
}

.accordionMap__area input[type=checkbox]:checked+label::after {
  top: 50%;
  transform: translateY(-50%) rotate(-135deg);
}

.accordionMap__area .accordionMap__box {
  overflow: hidden;
  max-height: 0;
  -webkit-transition: max-height 0.35s;
  transition: max-height 0.35s;
  color: #333;
  background: #fff;
}

.accordionMap__area input[type='checkbox']:checked+label+.accordionMap__box {
  max-height: 300vh;
  padding-bottom: 2em;
}

.accordionMap__contents+.accordionMap__contents {
  margin-top: 2em;
  border-top: 1px solid #ccc;
}

.accordionMap__area .accordionMap__box+input+label {
  border-top: 1px solid #fff;
}

.swiper {
  display: flex;
  margin: 2em auto 0;
  position: relative;
  overflow: hidden;
  list-style: none;
  padding: 0 0 2em 0;
  width: 100%;
}

.swiper-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  transform: translate3d(0, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
}

.swiper-slide {
  background: #fff;
  display: flex;
  justify-content: center;
  align-items: center;
  flex-shrink: 0;
  width: 100%;
  height: auto;
  position: relative;
  opacity: 0.8;
  transform: scale(0.8) translateY(11%);
  transition: transform 0.5s, opacity 0.5s;
}

.swiper-slide.swiper-slide-active {
  opacity: 1;
  transform: scale(1) translateY(0);
}

.swiper-slide img {
  width: 100%;
  height: auto;
}

.swiper-slide img.lazyload:not(.loaded) {
  width: auto;
  max-width: 100%;
}

.swiper-pagination {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  height: 1em !important;
  margin-top: 1em;
  display: flex;
  justify-content: center;
}

.swiper-pagination .swiper-pagination-bullet {
  width: 0.8em;
  height: 0.8em;
  display: block;
  border-radius: 0.4em;
  background-color: #ccc;
  margin: 0 0.4em;
}

.swiper-pagination .swiper-pagination-bullet.swiper-pagination-bullet-active {
  background-color: #333;
}

.itemDetail__box {
  margin-top: 2em;
  width: 100%;
  height: auto;
}

.itemDetail__box .head {
  color: #8e6647;
  font-size: 1.5em;
  font-weight: bold;
  text-align: center;
  margin-bottom: 0;
}

.itemDetail__box .text {
  font-size: 1em;
  color: #333;
  text-align: center;
  margin: 0;
}

.itemDetail__box .place__box {
  width: auto;
  height: auto;
  padding: 0.8em 1em;
  margin: 1em 0 0;
  background-color: #efefef;
  display: inline-block;
  position: relative;
  left: 50%;
  transform: translateX(-50%);
}

.itemDetail__box .place__box .place {
  color: #333;
  text-align: center;
  margin: 0;
}

.itemDetail__box .linkBtn {
  width: 100%;
  max-width: 400px;
  height: auto;
  margin: 1em auto 0;
  display: block;
}

.itemDetail__box .linkBtn img {
  width: 100%;
  height: auto;
  opacity: 1;
  transition: opacity 0.2s;
}

.itemDetail__box .linkBtn:hover img {
  opacity: 0.8;
}

img {
  width: 100%;
  height: auto;
}

p {
  margin: 0;
}

ul {
  list-style: none;
  padding-left: 0;
}

.tableSearch__area,
.tableSearch__area * {
  box-sizing: border-box;
}

.tableSearch__area {
  width: 100%;
  height: auto;
  font-size: 16px;
}

@media screen and (max-width: 600px) {
  .tableSearch__area {
    font-size: 10px;
  }
}

.tableSearch__area .tableSearch__headBox {
  width: 100%;
  height: auto;
  background-color: #007ab7;
  border-radius: 5px 5px 0 0;
  padding: 0.8em 0;
  border: 1px solid #007ab7;
}

.tableSearch__headBox .head {
  text-align: center;
  font-size: 1.5em;
  font-weight: bold;
  color: #fff;
}

.tableSearch__headBox .head ._bold {
  color: #F6CA06;
}

.tableSearch__box {
  border-style: solid;
  border-width: 1px 0 0 1px;
  border-color: #ccc;
  border-collapse: collapse;
}

.tableSearch__box thead th {
  background-color: #CBE6F3;
  border-style: solid;
  border-width: 0 1px 1px 0;
  border-color: #ccc;
  color: #333;
  font-weight: bold;
  text-align: center;
  padding: 0.5em 0;
}

.tableSearch__box tbody td {
  border-style: solid;
  border-width: 0 1px 1px 0;
  border-color: #ccc;
  width: 18%;
  padding: 1em 0.5em;
}

.tableSearch__box tbody td:first-of-type {
  width: 36%;
}

.itemLink {
  text-align: center;
}

.textLink {
  position: relative;
  color: #007ab7;
  font-weight: bold;
  display: block;
}

.textLink:after {
  content: '';
