  color: #ec4870;
  font-weight: 600;
}

.rating::before,
.rating::after {
  content: "★★★★★";
  color: #D6D6D6;
  position: absolute;
  top: 0;
  left: 0;
  transition: 0.5s;
}

.rating::after {
  color: #ffcc00;
  overflow: hidden;
  white-space: nowrap;
}

.rating[data-rating="0"]::after,
.rating[data-rating="0.0"]::after {
  width: calc(0%);
}

.rating[data-rating="0.1"]::after,
.rating[data-rating="0.1.0"]::after {
  width: calc(2%);
}

.rating[data-rating="0.2"]::after,
.rating[data-rating="0.2.0"]::after {
  width: calc(4%);
}

.rating[data-rating="0.3"]::after,
.rating[data-rating="0.3.0"]::after {
  width: calc(6%);
}

.rating[data-rating="0.4"]::after,
.rating[data-rating="0.4.0"]::after {
  width: calc(8%);
}

.rating[data-rating="0.5"]::after,
.rating[data-rating="0.5.0"]::after {
  width: calc(10%);
