.acc-table {
  border: 1px solid #cccccc;
  border-radius: 8px;
  overflow: hidden;
}

.acc-table .acc-head {
  position: relative;
  font-size: 18px;
  color: #333333;
  font-weight: bold;
  line-height: 1.2;
  cursor: pointer;
  border: 1px solid #cccccc;
  border-radius: 8px;
  background-color: #efefef;
  margin: -1px -1px 0;
  padding: 0.5em 0.5em 0.4em 2.2em;
}

.acc-table .acc-head::before,
.acc-table .acc-head::after {
  content: "";
  display: inline-block;
  width: 0.8em;
  height: 2px;
  background-color: #000000;
  position: absolute;
  top: calc(50% - 0.1em);
  left: 0.8em;
  -webkit-transform: none;
  transform: none;
}

.acc-table .acc-head::after {
  -webkit-transform: rotate(90deg);
  transform: rotate(90deg);
  transition: -webkit-transform 0.2s;
  transition: transform 0.2s;
  transition: transform 0.2s, -webkit-transform 0.2s;
}

.acc-table .acc-head.is-active::after {
  -webkit-transform: rotate(0);
  transform: rotate(0);
}

.acc-table .acc-head.is-active+.acc-body {
  height: auto;
  padding: 1em;
  opacity: 1;
  visibility: visible;
}

.acc-table .acc-body {
  visibility: hidden;
  height: 0;
  opacity: 0;
  padding-top: 0;
  padding-bottom: 0;
  overflow: hidden;
  transition: padding-top 0.25s, padding-bottom 0.25s, opacity 0.25s, visibility 0.25s, height 0.25s;
}

