.table-compare {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
  border-spacing: 0;
  text-align: center;
  font-size: 14px;
  line-height: 1.4;
}

.table-compare th {
  background-color: #00cdde;
  border: 1px solid #00cdde;
  color: #fff;
  font-weight: bold;
  padding: 25px 0;
  width: 20%;
  font-size: 12px;
}

.table-compare td {
  border: 1px solid #cccccc;
}

.table-compare a {
  text-decoration: none;
}

.table-compare .icon {
  margin: 0 auto;
  width: 80%;
  box-sizing: border-box;
}

.table-compare .icon img {
  max-width: 100%;
  height: auto;
  vertical-align: bottom;
  border-radius: 10px;
  overflow: hidden;
}

.table-compare .icon figcaption {
  font-size: 10px;
  color: #000000;
}

.table-compare .symbol {
  position: relative;
  display: inline-block;
  width: 52px;
  height: 52px;
}

.table-compare .symbol.circle::before {
  content: "";
  display: inline-block;
  width: 100%;
  height: 100%;
  border: 7px solid #000;
  border-radius: 50%;
  box-sizing: border-box;
}

.table-compare .symbol.double::after {
  content: "";
  display: inline-block;
  width: 50%;
  height: 50%;
  position: absolute;
  top: 25%;
  left: 25%;
  border: 7px solid #000;
  border-radius: 50%;
  box-sizing: border-box;
}

.table-compare .symbol.red::before,
.table-compare .symbol.red::after {
  border-color: #e60033;
}

.table-compare .symbol.yellow::before,
.table-compare .symbol.yellow::after {
  border-color: #f8b500;
}

.table-compare .note {
  font-size: 10px;
}

.table-compare .tag {
  display: block;
  width: 80%;
  border-radius: 5%;
  margin: 5px auto;
  box-shadow: 1px 1px 1px #dbdbdb;
  font-size: 10px;
  color: #fff;
  padding: 4px 3px;
}

.table-compare .tag.pink {
  background-color: #ed49b4;
}

.table-compare .tag.blue {
  background-color: #2D2DBB;
}

.table-compare .tag.green {
  background-color: #069100;
}

.table-compare .tag.yellow {
  background-color: #f0b137;
}

.timeline-table {
  width: 600px;
  max-width: 100%;
  margin: 0 auto;
  background-color: #fdeff2;
  padding: 20px 30px;
  box-sizing: border-box;
}

.timeline-table .caption-box {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
}

.timeline-table .caption-box p {
  margin: 0;
}

.timeline-table .caption-box .tag {
  display: inline-block;
  font-size: 14px;
  color: #ffffff;
  line-height: 1.2;
  background-color: #eb6ea5;
  text-align: center;
  padding: 5px 20px 3px;
  border-radius: 10px;
  box-sizing: border-box;
}

.timeline-table .caption-box .title {
  font-size: 16px;
  font-weight: bold;
}

.timeline-table .caption-box .note {
  font-size: 80%;
  margin-left: 6px;
}

.timeline-table .list-calendar {
  font-size: 16px;
  line-height: 1.5;
  font-weight: bold;
  width: 100%;
  display: flex;
  flex-wrap: wrap;
  margin: 20px 0 0;
  padding: 0;
  box-sizing: border-box;
}

.timeline-table .list-calendar dt,
.timeline-table .list-calendar dd {
  margin: 0;
  padding: 0 0 10px;
  box-sizing: border-box;
}

.timeline-table .list-calendar dt:nth-of-type(2n + 1),
.timeline-table .list-calendar dd:nth-of-type(2n + 1) {
  color: #e95295;
}

.timeline-table .list-calendar dt:nth-of-type(2n),
.timeline-table .list-calendar dd:nth-of-type(2n) {
  color: #999999;
}

.timeline-table .list-calendar dt {
  width: 6em;
  position: relative;
}

.timeline-table .list-calendar dt::before {
  content: "";
  width: 1px;
  height: 100%;
  background-color: #999999;
  position: absolute;
  top: 0.5em;
  right: 1em;
}

.timeline-table .list-calendar dt:last-of-type::before {
  content: none;
}

.timeline-table .list-calendar dt::after {
  content: "";
  width: calc(0.5em + 1px);
  height: calc(0.5em + 1px);
  border-radius: 100%;
  position: absolute;
  top: 0.45em;
  right: 0.75em;
}

.timeline-table .list-calendar dt:nth-of-type(2n + 1)::after {
  background-color: #e95295;
}

.timeline-table .list-calendar dt:nth-of-type(2n)::after {
  background-color: #999999;
}

.timeline-table .list-calendar dd {
  display: flex;
  width: calc(100% - 6em);
  padding-left: 20px;
  box-sizing: border-box;
}

.timeline-table .list-calendar dd>span {
  width: calc(100% / 3);
  padding: 0 5px;
  box-sizing: border-box;
}

