 .sticky-table .scroll-hint {
  width: 10em;
  aspect-ratio: 7/3;
  background-color: rgba(0, 0, 0, 0.5019607843);
  border-radius: 10px;
  padding: 0.75em 1.5em;
  box-sizing: border-box;
  display: grid;
  place-items: center;
  padding-bottom: 1.5rem;
  position: absolute;
  inset: 0;
  margin: auto;
  align-items: center;
  opacity: 1;
  pointer-events: all;
  transition: 0.5s;
}

 .sticky-table .scroll-hint::after {
  content: "スクロールできます";
  color: #fff;
  font-size: 0.5em;
  position: absolute;
  bottom: 0.25rem;
}

 .sticky-table .scroll-hint-hand.is-view {
  animation: handSwipe 1.5s ease-in-out 2;
}

 .sticky-table .scroll-hint img {
  object-fit: contain;
  width: 3em;
}

 .sticky-table .scroll-hint.is-active {
  opacity: 0;
  pointer-events: none;
}

@media (max-width: 500px) {
   .sticky-table {
    font-size: 3vw;
  }

   .sticky-table .scroll-hint::after {
    font-size: 0.8em;
  }
}

@keyframes handSwipe {
  0% {
    transform: translateX(100%);
    opacity: 1;
  }

  50% {
    transform: translateX(-100%);
    opacity: 0;
  }

  100% {
    transform: translateX(100%);
    opacity: 0;
  }
}

