.c-mark01:before,
.c-mark02:before,
.c-mark02:after,
.c-mark03::before,
.c-mark03::after {
  position: absolute;
  content: '';
  box-sizing: border-box;
}

.c-mark01 {
  width: 40px;
  height: 40px;
  margin: 0 auto;
  display: block;
  position: relative;
  text-indent: -10000px;
}

.c-mark01:before {
  width: 40px;
  height: 40px;
  border: 5px solid #f00;
  border-radius: 50%;
  bottom: -50%;
  right: 50%;
  transform: translate(50%, -50%);
}

.c-mark02 {
  width: 40px;
  height: 40px;
  margin: 0 auto;
  display: block;
  position: relative;
  text-indent: -10000px;
}

.c-mark02:before {
  width: 40px;
  height: 40px;
  border: 3px solid #ffaa00;
  border-radius: 50%;
  top: 0;
  right: 50%;
  transform: translateX(50%);
}

.c-mark02:after {
  width: 30px;
  height: 30px;
  border: 3px solid #ffaa00;
  border-radius: 50%;
  top: 5px;
  right: 50%;
  transform: translateX(50%);
}

.c-mark03 {
  width: 40px;
  height: 40px;
  margin: 0 auto;
  display: block;
  position: relative;
  text-indent: -10000px;
}

.c-mark03::before {
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 0 20px 34.6px 20px;
  border-color: transparent transparent #007bff transparent;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.c-mark03::after {
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 0 14px 24.2px 14px;
  border-color: transparent transparent #fff transparent;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
