}

.size-fit-parallel {
  display: flex;
  align-items: flex-start;
  width: 98%;
  margin-left: auto;
  margin-right: auto;
  text-align: center;
  position: relative;
  box-sizing: border-box;
}

.size-fit-parallel::before {
  content: "";
  height: 2px;
  background-color: #999999;
  width: calc(100% - (100% / 5));
  position: absolute;
  left: 10%;
  top: calc(20px / 2);
}

.size-fit-parallel .item {
  width: calc(100% / 5);
}

.size-fit-parallel input {
  display: none;
}

.size-fit-parallel input:checked+label::before {
  border-color: #000;
}

.size-fit-parallel input:checked+label::after {
  opacity: 1;
}

.size-fit-parallel label {
  display: block;
  position: relative;
  text-align: center;
  cursor: pointer;
  padding-top: calc(20px + 5px);
  -webkit-tap-highlight-color: transparent;
}

.size-fit-parallel label::before,
.size-fit-parallel label::after {
  content: "";
  border-radius: 50%;
  overflow: hidden;
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  box-sizing: border-box;
}

.size-fit-parallel label::before {
  width: 20px;
  height: 20px;
  border: solid 2px #ccc;
  background-color: #fff;
}

.size-fit-parallel label::after {
  width: calc(20px / 2);
  height: calc(20px / 2);
  background-color: #000;
  top: 5px;
  opacity: 0;
}

