.c-btn a:before {
  background-image: linear-gradient(90deg, hsla(0, 0%, 100%, 0), hsla(0, 0%, 100%, 0.6) 80%, hsla(0, 0%, 100%, 0));
  content: '';
  height: 200px;
  left: -120px;
  position: absolute;
  top: 50%;
  -webkit-transform: translateY(-50%) rotate(25deg);
  transform: translateY(-50%) rotate(25deg);
  width: 80px;
