/* ウィジェット全体 */
.c-ranking {
  width: 100%;
  max-width: 750px;
  margin: 0 auto 20px;
  box-sizing: border-box;
}

img {
  max-width: 100%;
  height: auto;
}

/* 見出し */
.p-ranking_ttl {
  font-size: 24px;
  font-weight: bold;
  color: #fff;
  text-align: center;
  width: 100%;
  margin: 0;
  margin-top: 50px;
  padding: 10px 0;
  background: #f00;
  position: relative;
  box-sizing: border-box;
  z-index: 1;
}

/* 見出し上の丸 */
.p-ranking_ttl:before {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  top: -40px;
  right: 50%;
  transform: translateX(50%);
  background: #f00 url(/uploads/9f176c41843412f43b6a9f9daa6420a0d88c867566254bed2e7d381a1c16c93f.png) no-repeat center top 15px/ 35px
    auto;
  position: absolute;
  content: '';
  z-index: -1;
}

/* テーブル */
.c-ranking_table {
  width: 100%;
  table-layout: fixed;
  border-spacing: 0;
}

/* スクロールでついてくる部分 */
.sticky {
  position: sticky;
  top: 0;
  left: 0;
  z-index: 2;
}

/* テーブル見出し */
.c-ranking_table thead {
  background: #fff;
}

.c-ranking_table thead th {
  border-bottom: 1px solid #ddd;
padding: 10px;
}

/* 一列目のセルの背景色 */
.c-ranking_table thead tr th:first-child,
.c-ranking_table tbody td:first-child {
  background: #ffffb1;
}

.c-ranking_table th,
.c-ranking_table td {
  text-align: center;
  box-sizing: border-box;
}

.c-ranking_table tbody th {
  color: #fff;
  background: #00f;
  padding: 10px 0;
}

.c-ranking_table thead th,
.c-ranking_table td {
  padding: 10px;
  border-left: 1px solid #ddd;
}

.c-ranking_table thead tr th:last-child,
.c-ranking_table tr td:last-child {
  border-right: 1px solid #ddd;
}

.c-ranking_table tbody tr:last-child td {
  border-bottom: 1px solid #ddd;
}

.c-ranking_table td span {
  position: relative;
  z-index: 1;
}

/* マーク全般共通設定 */
.m-single,
.m-double,
.m-triangle {
  position: relative;
}

/* マーク全般共通設定 */
.m-single:before,
.m-double:before,
.m-double:after,
.m-triangle:after,
.m-triangle:before {
  position: absolute;
  content: '';
  box-sizing: border-box;
}

/* ○の設定 */
.m-single:before {
  width: 40px;
  height: 40px;
  border: 5px solid #f00;
  border-radius: 50%;
  top: 50%;
  right: 50%;
  transform: translate(50%, -50%);
}

/* ◎の設定 */
.m-double:before {
  width: 40px;
  height: 40px;
  border: 3px solid #ffaa00;
  border-radius: 50%;
  top: 50%;
  right: 50%;
  transform: translate(50%, -50%);
}

/* ◎の設定 */
.m-double:after {
  width: 30px;
  height: 30px;
  border: 3px solid #ffaa00;
  border-radius: 50%;
  top: 50%;
  right: 50%;
  transform: translate(50%, -50%);
}

/* △の設定 */
.m-triangle:before {
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 0 20px 34.6px 20px;
  border-color: transparent transparent #007bff transparent;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

/* △の設定 */
.m-triangle:after {
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 0 14px 24.2px 14px;
  border-color: transparent transparent #fff transparent;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  margin-top: 1.7px;
}

/* 太文字 */
.bold {
  font-weight: bold;
}

/* 赤文字 */
.red {
  color: #f00;
}

/* 星の設定 */
.star-rating {
  /*星の数をHTML欄で変更したあとに下記数値を変更ください*/
  width: 5em;
  height: 2em;
  font-size: 25px;
  position: relative;
  margin: 0 auto;
}

.star-rating-front {
  position: absolute;
