  /* 横幅 */
  width: 820px;
  /* 文字サイズ */
  font-size: 15.5px;
  /* 背景色 */
  background: #fff9e5;
  /* 内側余白|上下|左右| */
  padding: 0.5rem 1.1rem;
  /* 外側余白|上下|左右| */
  margin: 2rem 0;
  /* 枠線|タイプ|太さ|色| */
  border: solid 3px #f7931e;
  /* 角の丸み */
  border-radius: 0.5rem;
  position: relative;
  box-sizing: border-box;
}

/* 右の折り目 */
.l-ollist__box:after {
  /* 右からの距離 */
  right: -3px;
  /* 上からの距離 */
  top: -3px;
  /* 大きさ */
  border-width: 0 30px 30px 0;
  /* 色 */
  border-color: #f7931e #fff #f7931e;
  border-style: solid;
  /* シャドウ|水平方向の距離|垂直方向の距離|ぼかし|色| */
  box-shadow: -1px 1px 1px rgb(0 0 0 / 15%);
  position: absolute;
  content: "";
  box-sizing: border-box;
}

/* 全体タイトル */
.l-ollist__box__ttl {
  /* 文字色 */
  color: #f7931e;
  /* 文字サイズ */
  font-size: 1.25rem;
  /* 文字の太さ|bold=太い|normal=普通| */
  font-weight: bold;
  /* 下線|タイプ(dotted=ドット,solid=直線)|太さ|色| */
  border-bottom: dotted 3px #f7931e;
  /* 外側下余白 */
  margin-bottom: 0.8rem;
  /* 内側余白|上|左右|下| */
  padding: 0 1rem 0.5rem 2rem;
  /* 行間 */
  line-height: 1.4;
  position: relative;
  box-sizing: border-box;
}

.l-ollist__box__ttl:before,
.l-ollist__box__ttl:after {
  position: absolute;
  content: "";
}

/* チェックマークの丸 */
.l-ollist__box__ttl:before {
  /* 横幅 */
  width: 20px;
  /* 縦幅 */
  height: 20px;
  /* 色 */
  background: #f7931e;
  /* 角の丸み */
  border-radius: 50%;
  /* 左からの距離 */
  left: 5px;
  /* 上からの距離 */
  top: 5px;
}

/* チェックマーク */
.l-ollist__box__ttl:after {
  /* 横幅 */
  width: 10px;
  /* 縦幅 */
  height: 5px;
  /* 左の線|太さ|タイプ|色| */
  border-left: 2.5px solid #fff;
  /* 右の線|太さ|タイプ|色| */
  border-bottom: 2.5px solid #fff;
  /* 左からの距離 */
  left: 8px;
  /* 上からの距離 */
  top: 10px;
  transform: rotate(315deg);
}

/* リスト全体 */
.l-ollist__box__ol {
  /* 外側余白|上|左右|下| */
  margin: 0.5rem 0 0.7rem;
  /* 内側余白|上下左右| */
  padding: 0;
  list-style-type: none;
  counter-reset: number;
  box-sizing: border-box;
}

/* リストそれぞれ */
.l-ollist__box__ol__item {
  /* 内側余白|上|右|下|左| */
  padding: 0.5em 0 0.5em 34px;
  /* 行間 */
  line-height: 1.5em;
  position: relative;
  box-sizing: border-box;
}

/* リスト数字マーク */
.l-ollist__box__ol__item:before {
  /* 横幅 */
  width: 25px;
  /* 縦幅 */
  height: 25px;
  /* 外側余白 */
  margin: 0;
  /* 文字色 */
  color: #fff;
  /* 背景色 */
  background: #f7931e;
  /* フォント */
  font-family: Quicksand, sans-serif;
  /* 文字サイズ */
  font-size: 15px;
  /* 文字の太さ(700=太い,400=普通) */
  font-weight: 700;
  /* 左からの距離 */
  left: 0;
  /* 角の丸み */
  border-radius: 50%;
  /* 行間 */
  line-height: 25px;
  text-align: center;
  vertical-align: middle;
  content: counter(number);
  counter-increment: number;
  display: inline-block;
  position: absolute;
}

/* 強調部分 */
.l-ollist__box__ol__item>strong {
  /* 文字の太さ(700=太い,400=普通) */
  font-weight: 700;
  display: block;
  margin: 0;
  padding: 0;
}

.l-ollist__box__ol__item>p {
  margin: 0;
  padding: 0;
}

/* widget全体の設定 */
.accordionContents__area {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* アコーディオン1つ分の設定 */
.accordionContents__area .items {
  position: relative;
  /* 見出しとアコーディオンの中身を画像にする場合は以下のコメントアウトを外してください　（行間） */
  /* line-height: 0; */
}



/* 見出し部分 */
.accordionContents__area .accordion__head {
  position: relative;
  z-index: 1;
  /* カーソルが要素に触れた時、指になる */
  cursor: pointer;

  /* 見出しを画像にする場合は以下をコメントアウトしてください（上から、背景色/文字色/文字の大きさ/文字の太さ/内側の余白） */
  background-color: #1c85d8;
  color: #fff;
  font-size: 26px;
  font-weight: bold;
  padding: 20px 5%;
  /* 画像にする場合のコメントアウトはここまで */
}



/* 開閉時の+→ーのアイコン */
.accordionContents__area .accordion__head:before,
 .accordionContents__area .accordion__head:after {
  display: flex;
  content: '';
  /* アイコンの色 */
  background-color: #fff;
  /* 角丸 */
  border-radius: 10px;
  /* 横幅 */
  width: 18px;
  /* 高さ */
  height: 4px;
  position: absolute;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（右基準） */
  right: 20px;
  /* 回転｜Y軸位置 */
  transform: rotate(0deg) translateY(-50%);
  /* 基準位置 */
  transform-origin: center center;
  /* アニメーションの速さ */
  transition-duration: 0.2s;
}

 .accordionContents__area .accordion__head:before {
  /* 横幅 */
  width: 4px;
  /* 高さ */
  height: 18px;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（右基準） */
  right: 27px;
}



/* 開閉時のアイコン */
.accordionContents__area .accordion__head.is-open:before {
  /* 非表示 */
  content: none;
}



/* 開閉時のアイコン */
.accordionContents__area .accordion__head.is-open:after {
  /* 回転 */
  transform: rotate(-360deg);
}



/* 見出しが画像の場合 */
.accordionContents__area .accordion__head img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  z-index: -1;
}



/* アコーディオンの中身 */
.accordionContents__area .accordion__inner {
  box-sizing: border-box;
  /* 初期非表示 */
  display: none;

  /* アコーディオンの中身を画像にする場合は以下をコメントアウトしてください（上から、内側の余白｜左側の線（太さ｜線種｜色）｜右側の線（同様）｜下側の線（同様） */
  padding: 30px 5%;
  border-left: 2px solid #1c85d8;
  border-right: 2px solid #1c85d8;
  border-bottom: 2px solid #1c85d8;
  /* 画像にする場合のコメントアウトはここまで */
}



/* アコーディオンの中身をテキストで利用する場合 */
.accordionContents__area .accordion__inner .text {
  /* 文字の大きさ */
  font-size: 16px;
  /* 文字色 */
  color: #333;
  /* 文字の位置 */
  text-align: left;
}



/* アコーディオンの中身が画像の場合 */
.accordionContents__area .accordion__inner img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}

/* 最大幅をデフォルト値の750から変更する場合は、他の要素で設定しているcalc()内のデフォルト値750を最大幅と同じに設定してください */

/*-- 全体の設定 --*/
.accordionMenu__box {
  /* 横幅 */
  width: 100%;
  /* 最大幅 */
  max-width: 750px;
  /*背景の色*/
  background: #fff;
  /* 内側の余白 */
  padding: 0;
  /* 外側の余白|上|左右auto=自動|下| */
  margin: 0 auto 20px;
  box-sizing: border-box;
}

/*-- アコーディオン（インデックス）内の見出し --*/
.accordionMenu__box .accordionMenu__contents .menu_title {
  /* 文字色 */
  color: #fff;
  /* 背景色 */
  background: #fd778d;
  /* 外側の余白|上|左右auto=自動|下| */
  margin: 10px auto 0;
  /* 内側余白|上下|左右|*/
  padding: calc(100% * (30 / 750)) 0 calc(100% * (30 / 750)) calc(100% * (30 / 750));
  /*文字の大きさ*/
  font-size: 36px;
  /*文字の太さ*/
  font-weight: normal;
  display: flex;
  -ms-flex-pack: justify;
  justify-content: space-between;
  align-items: center;
  box-sizing: border-box;
  position: relative;
}

.accordionMenu__box .accordionMenu__contents .menu_title:first-of-type {
  margin-top: 0;
}

.accordionMenu__box .accordionMenu__contents .menu_title:hover {
  cursor: pointer;
}

.accordionMenu__box .accordionMenu__contents .menu_title .menu_titleBox {
  width: calc(100% - 30px);
}

/*-- インデックスのボタン部分 --*/
.accordionMenu__box .accordionMenu__contents .menu_title .menutoggle_btn {
  /*ボタンの横幅*/
  /* width: calc(100vw * (40 / 750)); */
  /*ボタンの高さ*/
  /* height: calc(100vw * (40 / 750)); */
  /* 外側の余白 */
  margin: 0;
  /* 内側の余白 */
  padding: 0;
  box-sizing: border-box;
}

/* プラス(+)印 */
.accordionMenu__box .accordionMenu__contents .menu_title .menutoggle_btn:before,
.accordionMenu__box .accordionMenu__contents .menu_title .menutoggle_btn:after {
  /* 色 */
  background: #fff;
  content: "";
  display: block;
  position: absolute;
}

/* プラス(+)印の縦線(|)部分 */
.accordionMenu__box .accordionMenu__contents .menu_title .menutoggle_btn:before {
  /* 横幅 */
  width: calc(100vw * (4 / 750));
  /* 縦幅 */
  height: calc(100vw * (40 / 750));
  top: 0;
  bottom: 0;
  /* right: calc(1px * (30 + 20 - 2)); */
  right: calc(100% * ((30 + 20 - 2) / 750));
  min-width: 1px;
  max-width: 4px;
  margin: auto 0;
  max-height: 40px;
  transition: opacity 0.2s;
}

/* プラス(+)印の横線(-)部分 */
.accordionMenu__box .accordionMenu__contents .menu_title .menutoggle_btn:after {
  /* 横幅 */
  width: calc(100vw * (40 / 750));
  max-width: 40px;
  /* 縦幅 */
  height: calc(100vw * (4 / 750));
  top: 0;
  bottom: 0;
  /* right: min(20px, calc((100vw * (40 / 750)) / 2 - 0.5px)); */
  right: calc(100% * (30 / 750));
  min-height: 1px;
  max-height: 4px;
  margin: auto 0;
}

.accordionMenu__box .accordionMenu__contents .menu_title .menutoggle_btn.active:before {
  opacity: 0;
}

/*-- インデックス詳細部分 --*/
.accordionMenu__box .accordionMenu__contents .menu_content {
  /*文字の大きさ*/
  font-size: 16px;
  /*コンテンツ左の余白（不要の場合は「0」としてください）*/
  margin-left: 0;
  /*コンテンツ下の余白（不要の場合は「0」としてください）*/
  margin-bottom: 10px;
  /*コンテンツが表示されている時の下側の余白*/
  padding-bottom: 10px;
  overflow: hidden;
  transition-timing-function: ease;
  display: none;
  box-sizing: border-box;
}

/*-- インデックス詳細部分 - テーブル --*/
.accordionMenu__box .accordionMenu__contents .menu_content table {
  /* 横幅 */
  width: 100%;
  border-collapse: collapse;
  box-sizing: border-box;
}

.accordionMenu__box .accordionMenu__contents .menu_content table th,
.accordionMenu__box .accordionMenu__contents .menu_content table td {
  /* 文字色 */
  color: #1b1b1b;
}

/*-- インデックス詳細部分 - テーブル見出し --*/
.accordionMenu__box .accordionMenu__contents .menu_content table tr th {
  /* 文字サイズ */
  font-size: 30px;
  /* 行間 */
  line-height: 69px;
  /* 横幅 */
  width: calc(100% * (150 / 750));
  /* 文字の太さ */
  font-weight: normal;
  /* 内側の余白|上下|左右 */
  padding: 11px 0 11px 0;
  /* 水平位置の寄せ */
  vertical-align: top;
}

/* スマホ(ウィンドウ幅750px以下)の場合の設定 */
@media screen and (max-width: 750px) {
  .accordionMenu__box .accordionMenu__contents .menu_content table tr th {
    padding: calc(100vw * (11 / 750)) 0 calc(100vw * (11 / 750)) 0;
    font-size: calc(100vw * (30 / 750));
    line-height: calc(100vw * (69 / 750));
  }
}

/*-- インデックス詳細部分 - テーブル見出し奇数行の背景 --*/
.accordionMenu__box .accordionMenu__contents .menu_content table tr:nth-child(odd) th {
  /* 背景色 */
  background: #ffe3ef;
}

/*-- インデックス詳細部分 - テーブル見出し偶数行の背景 --*/
.accordionMenu__box .accordionMenu__contents .menu_content table tr:nth-child(even) th {
  /* 背景色 */
  background: #ffd5e7;
}

/*-- インデックス詳細部分 - テーブル内容 --*/
.accordionMenu__box .accordionMenu__contents .menu_content table tr td {
  /* 内側の余白|上下|左右 */
