  line-height: 69px;
}

@media screen and (max-width: 750px) {
  .accordionMenu__box .accordionMenu__contents .menu_content table tr td {
    padding: calc(100vw * (11 / 750)) 0 0 calc(100vw * (30 / 750));
    font-size: calc(100vw * (30 / 750));
    line-height: calc(100vw * (69 / 750));
  }
}

/*-- インデックス詳細部分 - テーブル内容奇数行の背景 --*/
.accordionMenu__box .accordionMenu__contents .menu_content table tr:nth-child(odd) td {
  /* 背景色 */
  background: #fff7fa;
}

/*-- インデックス詳細部分 - テーブル内容偶数行の背景 --*/
.accordionMenu__box .accordionMenu__contents .menu_content table tr:nth-child(even) td {
  /* 背景色 */
  background: #ffeaf3;
}

/*-- インデックス詳細部分 - テーブル内容 リスト --*/
.accordionMenu__box .accordionMenu__contents .menu_content table tr td ul {
  /* 外側の余白|上下左右| */
  margin: 0;
  /* 内側の余白|上下左右| */
  padding: 0;
  /* 横並び */
  display: inline-flex;
