}

/*-- インデックス詳細部分 - テーブル内容 リストそれぞれ --*/
.accordionMenu__box .accordionMenu__contents .menu_content table tr td li {
  /* 内側の余白|上|右|下|左| */
  padding: 0 1em 0.5em 0;
  box-sizing: border-box;
  position: relative;
}

/* リンクテキストの間の区切り線 */
.accordionMenu__box .accordionMenu__contents .menu_content table tr td li:before {
  /* 色 */
  background: #000;
  /* 不要な場合は下記""をnoneに変更 */
  content: "";
  /* 横幅 */
  width: 1px;
  /* 縦幅 */
  height: 1em;
  right: 0.5em;
  top: 50%;
  transform: translateY(calc(-50% - 0.25em));
  position: absolute;
}

/* リンク */
.accordionMenu__box .accordionMenu__contents .menu_content table tr td li a {
