.productIntro__inner .img__box,
.productIntro__inner .info__box,
.productIntro__inner .btn__box {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* 商品画像の箱 */
.productIntro__inner .img__box {
  /* X方向の位置 */
  grid-column: 1 / 2;
  /* Y方向の位置 */
  grid-row: 1 / 3;
}



/* 商品名部分の箱 */
.productIntro__inner .info__box {
  /* X方向の位置 */
  grid-column: 3 / 4;
  /* Y方向の位置 */
  grid-row: 1 / 2;
}



/* ボタン部分の箱 */
.productIntro__inner .btn__box {
  /* X方向の位置 */
  grid-column: 3 / 4;
  /* Y方向の位置 */
  grid-row: 2 / 3;
}



/* 商品画像 */
.img__box img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* 商品名の段落設定 */
.info__box p {
  /* 外側の余白 */
  margin: 0;
}



/* 会社名 */
.info__box .company {
  /* 文字の大きさ */
  font-size: 16px;
}



/* 商品名 */
.info__box .product {
  /* 文字の大きさ */
  font-size: 22px;
  /* 文字の太さ */
  font-weight: bold;
}



/* 価格 */
.info__box .price {
  /* 文字の色 */
  color: #ff6251;
  /* 文字の大きさ */
  font-size: 18px;
}



/* 価格の小さい文字 */
.info__box .price ._small {
  /* 文字の大きさ */
  font-size: 10px;
}



/* 円、（税込）部分 */
.info__box .price .yen {
  /* 文字の大きさ */
  font-size: 12px;
}



/* ボタンの箱 */
.btn__box {
  /* 外側の上余白 */
  margin-top: 20px;
}



/* ボタン */
.btn__box .btn {
  /* 横幅 */
  width: 90%;
  /* 最大幅 */
  max-width: 305px;
  /* 高さ */
  height: 38px;
  /* 外側の余白 */
  margin: 10px auto 0;
  /* 内側の余白 */
  padding: 10px 0;
  display: block;
  /* 角丸 */
  border-radius: 6px;
  /* 文字の大きさ */
  font-size: 15px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の位置 */
  text-align: center;
  /* テキストの装飾 */
  text-decoration: none;
  /* 行間 */
  line-height: 1.2;
  /* 文字の色 */
  color: #fff;
}



/* ボタン内の価格部分 */
.btn .btnPrice {
  /* 文字の大きさ */
  font-size: 11px;
}



/* ボタン部分のコメント */
.comment {
  /* 文字の位置 */
  text-align: center;
  /* 文字の大きさ */
  font-size: 14px;
}



/* コメントの下にボタンがある場合 */
.comment+.btn {
  /* 外側の上余白 */
  margin-top: 5px;
}



/* ボタンの下にコメントがある場合 */
.btn+.comment {
  /* 外側の上余白 */
  margin-top: 10px;
}



/* 商品詳細の箱 */
.productIntro__detail {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 外側の上余白 */
  margin-top: 20px;
}



/* 商品詳細の見出し */
.productIntro__detail .head {
  /* 文字の大きさ */
  font-size: 24px;
  /* 文字の太さ */
  font-weight: bold;
  /* 外側の余白 */
  margin: 0;
}



/* 商品詳細文 */
.productIntro__detail .text {
  /* 文字の大きさ */
  font-size: 15px;
  /* 外側の余白 */
  margin: 10px 0 0;
}



/* テーブル部分 */
.detail__table {
  /* 横幅 */
  width: 100%;
  /* 上線｜太さ｜線種｜色｜ */
  border-top: 1px solid #eeeeee;
  /* 左線｜太さ｜線種｜色｜ */
  border-left: 1px solid #eeeeee;
  /* 文字の大きさ */
  font-size: 12px;
  /* 行間 */
  line-height: 1.4;
  /* テーブル内の余白 */
  border-collapse: collapse;
  /* 外側の上余白 */
  margin-top: 20px;
}



/* テーブル見出し */
.detail__table th {
  /* 背景色 */
  background: #f9f9f9;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 1px solid #eeeeee;
  /* 右線｜太さ｜線種｜色｜ */
  border-right: 1px solid #eeeeee;
  /* 文字の太さ */
  font-weight: normal;
  /* 文字の位置 */
  text-align: left;
  /* 内側の余白 */
  padding: 10px;
  /* テーブル内のテキストの位置（Y軸） */
  vertical-align: top;
  /* 横幅 */
  width: 20%;
  /* 最大幅 */
  max-width: 120px;
}



/* テーブル内の詳細 */
.detail__table td {
  /* 内側の余白 */
  padding: 10px;
  /* テーブル内のテキストの位置（Y軸） */
  vertical-align: top;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 1px solid #eeeeee;
  /* 右線｜太さ｜線種｜色｜ */
  border-right: 1px solid #eeeeee;
}

/* レスポンシブ（初期600px以下、適宜設定してください） */
@media screen and (max-width:600px) {


  /* widget全体 */
  .productIntro__area {
    /* 線｜太さ｜線種｜色｜ */
    border: none;
  }



  /* 商品画像、商品名、ボタン部分 */
  .productIntro__inner {
    /* 横幅 */
    width: 100%;
    /* 高さ */
    height: auto;
    display: grid;
    /* グリッドの設定（X方向） */
    grid-template-columns: 100%;
    /* グリッドの設定（Y方向） */
    grid-template-rows: auto auto auto;
  }



  /* 商品画像の箱 */
  .productIntro__inner .img__box {
    /* X方向の位置 */
    grid-column: 1 / 2;
    /* Y方向の位置 */
    grid-row: 2 / 3;
    /* 外側の上余白 */
    margin-top: 20px;
  }



  /* 商品名部分の箱 */
  .productIntro__inner .info__box {
    /* X方向の位置 */
    grid-column: 1 / 2;
    /* Y方向の位置 */
    grid-row: 1 / 2;
    /* 内側の余白 */
    padding: 5px 10px;
    /* 背景色 */
    background: #eee;
    /* 外側の余白 */
    margin: 0 calc(50% - 50vw);
    /* 横幅 */
    width: 100vw;
    /* 最大幅 */
    max-width: none;
    box-sizing: border-box;
  }



  /* ボタン部分の箱 */
  .productIntro__inner .btn__box {
    /* X方向の位置 */
    grid-column: 1 / 2;
    /* Y方向の位置 */
    grid-row: 3 / 4;
  }



  /* 会社名 */
  .info__box .company {
    /* 文字の大きさ */
    font-size: 12px;
  }



  /* 価格 */
  .info__box .price {
    /* 文字の太さ */
    font-weight: bold;
  }



  /* 商品詳細の見出し */
  .productIntro__detail .head {
    /* 文字の大きさ */
    font-size: 20px;
  }



  /* テーブル見出し */
  .detail__table th {
    /* 横幅 */
    width: 35%;
  }
}

/* ウィジェット全体 */
.l-flow_step {
  /* 横幅 */
  width: 100%;
  /* 最大幅 */
  max-width: 780px;
  /* 外側余白|上|左右auto=自動|下| */
  margin: 0 auto 20px;
  /* 内側余白|上下左右| */
  padding: 0;
  box-sizing: border-box;
}

/* タイトル */
.l-flow_step__ttl {
  /* 文字サイズ */
  font-size: 20px;
  /* 文字の太さ */
  font-weight: bold;
  /* 背景色 */
  background: #ff99ff;
  /* 文字色 */
  color: #fff;
  /* 外側余白|上|左右|下| */
  margin: 0 0 10px;
  /* 内側余白|上下|左右| */
  padding: 5px 10px;
}

.l-flow_step__wrap {
  display: flex;
}

/* 左のバー */
.l-flow_step__bar {
  /* 横幅 */
  width: 5vw;
  /* 最大幅 */
  max-width: 35px;
  /* 縦幅 */
  height: auto;
  /* 背景色 */
  background: #ff99ff;
  /* 文字色 */
  color: #fff;
  /* 角の丸み */
  border-radius: 18px;
  /* 外側余白|上|右|下|左| */
  margin: 0 10px 10px 0;
  /* 内側余白|上下|左右| */
  padding: 0 10px;
  /* 文字の縦書き */
  writing-mode: vertical-rl;
  /* 字間 */
  letter-spacing: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
}

.l-flow_step__wrap:last-of-type .l-flow_step__bar {
  margin-bottom: 0;
}

/* リストスタイルリセット */
.l-flow_step__list,
.l-flow_step__list__item__cont__list {
  list-style-type: none;
  /* 外側余白|上下左右| */
  margin: 0;
  /* 内側余白|上下左右| */
  padding: 0;
}

/* 各STEP全体 */
.l-flow_step__list__item {
  /* 横並び */
  display: flex;
  /* 外側余白|上下左右| */
  margin: 0;
  box-sizing: border-box;
  position: relative;
}

/* STEPの下の縦線 */
.l-flow_step__list__item:before {
  /* 横幅 */
  width: 4px;
  /* 縦幅 */
  height: 100%;
  /* 背景色 */
  background: #ddd;
  /* 左からの距離 */
  left: 29px;
  /* 上からの距離 */
  top: 0;
  content: "";
  position: absolute;
}

/* STEP部分 */
.l-flow_step__num {
  /* 枠線|太さ|タイプ|色| */
  border: 1px solid #000;
  /* 背景色 */
  background: #fff;
  /* 角の丸み */
  border-radius: 50%;
  /* 横幅 */
  width: 60px;
  /* 縦幅 */
  height: 60px;
  /* 外側上余白 */
  margin-top: 10px;
  /* 外側右余白 */
  margin-right: 10px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  position: relative;
}

/* STEP部分 - 上の文字 */
.l-flow_step__num__text {
  /* 文字サイズ */
  font-size: 10px;
  display: block;
}

/* STEP部分 - 下の数字 */
.l-flow_step__num__chara {
  /* 文字サイズ */
  font-size: 20px;
  display: block;
  line-height: 1;
}

/* 右の内容 */
.l-flow_step__list__item__cont {
  /* 内側の余白|上下|左右| */
  padding: 20px 0;
  box-sizing: border-box;
  display: flex;
}

/* 見出し */
.l-flow_step__list__item__cont__ttl {
  /* 文字サイズ */
  font-size: 20px;
  /* 文字色 */
  color: #ff99ff;
  /* 文字の太さ */
  font-weight: bold;
  /* 外側下余白 */
  margin-bottom: 10px;
}

/* スマホで表示する見出し上部分 */
.l-flow_step__list__item__cont__ttl__mini {
  /* 文字サイズ */
  font-size: 14px;
}

.l-flow_step__list__item__cont__text {
  /* 外側下余白 */
  margin-bottom: 10px;
}

/* 要素下の枠線 */
.l-flow_step__list__item:not(:last-of-type) .l-flow_step__list__item__cont {
  /* 枠線下|太さ|タイプ|色| */
  border-bottom: 1px dotted #000;
}

/* 注釈 */
.l-flow_step__list__item__cont__caution {
  /* 文字サイズ */
  font-size: 14px;
  /* 外側余白|上|左右|下| */
  margin: 10px 0 0;
}

/* ボタン */
.l-flow_step__list__item__cont__btn {
  /* 外側余白上 */
  margin-top: 10px;
  display: inline-block;
}

.l-flow_step__list__item__cont__btn a {
  /* 内側余白|上下|左右| */
  padding: 10px 20px;
  /* 文字サイズ */
  font-size: 16px;
  /* 文字色 */
  color: #fff;
  /* 背景色 */
  background: #ff99ff;
  /* 文字並び|center=中央|left=左|right=右| */
  text-align: center;
  /* 角の丸み */
  border-radius: 20px;
  text-decoration: none;
  display: block;
  transition: all 0.3s;
}

/* ボタン マウスを乗せた時 */
.l-flow_step__list__item__cont__btn a:hover {
  /* 透明度（0~1） */
  opacity: 0.7;
}

/* 画像 */
.l-flow_step__image {
  /* 外側余白左 */
  margin-left: 10px;
}

/* 画像 */
.l-flow_step__image img {
  /* 最大横幅 */
  max-width: 100%;
  height: auto;
  vertical-align: middle;
}

/* リスト各行 */
.l-flow_step__list__item__cont__list__item {
  /* 内側余白左 */
  padding-left: 15px;
  /* 外側余白下 */
  margin-bottom: 5px;
  position: relative;
}

/* リスト各行左の点 */
.l-flow_step__list__item__cont__list__item:before {
  /* 横幅 */
  width: 4px;
  /* 縦幅 */
  height: 4px;
  /* 角の丸み */
  border-radius: 50%;
  /* 背景色 */
  background: #000;
  /* 左からの距離 */
  left: 3px;
  /* 上からの距離 */
  top: 0.7em;
  margin: 0 !important;
  content: "";
  position: absolute;
}

/* スマホだけに表示させる要素につけるクラス */
.sp-only {
  display: none;
}

/* スマホスタイル max-width:760px 以下の場合 */
@media screen and (max-width: 760px) {
  .l-flow_step__list__item:before {
    content: none;
  }

  .l-flow_step__num {
    display: none;
  }

  .l-flow_step__list__item__cont {
    display: block;
  }

  .l-flow_step__image {
    margin-top: 10px;
    margin-left: 0;
  }

  .sp-only {
    display: block;
  }
}

