/* 全体の設定 */
.accordion__area {
  /* 横幅 */
  width: 100%;
  /* 外側の余白 */
  margin: 0 auto;
}



/* 初期で表示されてる側のエリア */
.visible__box {
  /* 横幅 */
  width: calc(100% - 20px);
  /* 線｜線種｜太さ｜色｜ */
  border: solid 2px #ffe877;
  /* 内側の余白 */
  padding: 10px;
  /* 外側の下余白 */
  margin-bottom: 20px;
}



/* 初期で非表示にされてる側のエリア */
.hidden__box {
  /* 横幅 */
  width: calc(100% - 20px);
  /* 線｜線種｜太さ｜色｜ */
  border: solid 2px #B492CC;
  /* 内側の余白 */
  padding: 10px;
  /* 外側の下余白 */
  margin-bottom: 20px;
  /* 初期、非表示 */
  display: none;
}



/* ボタン */
.btn {
  /* 横幅 */
  width: 250px;
  /* 高さ */
  height: 80px;
  /* 文字の位置 */
  text-align: center;
  /* 文字の大きさ */
  font-size: 20px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の色 */
  color: #333;
  /* 外側の余白 */
  margin: 0 auto;
  /* 内側の下余白 */
  padding-bottom: 30px;
  display: block;
  /* 背景色 */
  background: #ffe877;
  /* 線｜線種｜太さ｜色｜ */
  border: none;
  /* 角丸 */
  border-radius: 8px;
  /* 影｜X軸｜Y軸｜ぼかし｜色｜ */
  box-shadow: 0 3px 0 rgba(0, 0, 0, 0.2);
  position: relative;
  /* カーソルで触れたら指になる */
  cursor: pointer;
  /* 回転 */
  transform: rotate(0);
  /* アニメーションの速さ */
  transition: transform 0.3s;
}



/* クリック時のボタン */
.btn.is-down {
  /* アニメーションの速さ */
  transition: transform 0.3s;
  /* 回転 */
  transform: rotate(180deg);
}



/* ボタンのテキスト */
.btn .text {
  /* 透明度 */
  opacity: 1;
  /* アニメーションの速さ */
  transition: all 0.2s;
}



/* クリック時のボタンのテキスト */
.btn.is-down .text {
  /* 透明度 */
  opacity: 0;
}



/* ボタンの矢印 */
.btn:after {
  content: '';
  /* 横幅 */
  width: 15px;
  /* 高さ */
  height: 15px;
  /* 右線｜太さ｜線種｜色｜ */
  border-right: 2px solid #666;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 2px solid #666;
  /* 回転、X軸の位置 */
  transform: rotate(45deg) translateX(-50%);
  display: block;
  position: absolute;
  /* 表示位置（下基準） */
  bottom: 15px;
  /* 表示位置（左基準） */
  left: 50%;
  /* アニメーションの速さ */
  transition: all 0.2s;
}



/* ボタンhover時 */
.btn:hover:after {
  /* hover時の表示位置（下基準） */
  bottom: 5px;
}

