/* チェックボックスの装飾（チェックマーク） */
.cp_ipcheck .option-input:before {
  position: absolute;
  z-index: 1;
  /* 縦位置（上基準） */
  top: -0.2rem;
  /* 横位置（左基準） */
  left: 4px;
  /* 横幅 */
  width: 0.75rem;
  /* 高さ */
  height: 0.375rem;
  content: '';
  /* アニメーション */
  transition: transform 0.4s cubic-bezier(0.45, 1.8, 0.5, 0.75);
  /* チェックマークの回転、大きさ */
  transform: rotate(-45deg) scale(0, 0);
  /* 線｜太さ｜線種｜色｜ */
  border: 2px solid #da3c41;
  /* 上線 */
  border-top-style: none;
  /* 右線 */
  border-right-style: none;
}



