/* プラスマイナスマーク */
.accordionlayers__mark {
  /* 横幅 */
  width: 20px;
  /* 縦幅 */
  height: 20px;
  pointer-events: none;
  text-indent: -10000px;
  position: relative;
}

.accordionlayers__mark:before {
  /* 横幅 */
  width: 20px;
  /* 縦幅 */
  height: 2px;
  /* 色 */
  background: #000;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  position: absolute;
  content: "";
}

.accordionlayers__mark:after {
  /* 縦幅 */
  height: 20px;
  /* 横幅 */
  width: 2px;
  /* 色 */
  background: #000;
  top: 0;
  right: 50%;
  transform: translateX(50%);
  position: absolute;
  content: "";
}

.trigger-open.opened .accordionlayers__mark:after {
  content: none;
}

/* 全体の設定 */
.accordion-area {
  /* 横幅（PC表示時） */
  width: 700px;
  /* 最大幅 */
  max-width: 100%;
  /* 高さ */
  height: auto;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 0 auto;
}



/* アコーディオンのボタンとなる部分 */
.accordion-area .accordionHead {
  /* 横幅（全体幅　-　左右余白） */
  width: 93%;
  /* 高さ */
  height: auto;
  /*内側の余白｜上余白｜右余白｜下余白｜左余白｜*/
  padding: 10px 0 10px 7%;
  /* 外側の余白 */
  margin: 0;
  /* 背景色｜グラデーション：方向[下へ]｜最初の色｜最後の色 */
  background: linear-gradient(to bottom, #fff, #e7e5e0);
  /* 影｜X方向｜Y方向｜ぼかし｜角丸｜色（赤, 緑, 青, 透明度）｜ */
  box-shadow: 0 2px 3px 0 rgba(0, 0, 0, 0.3);
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #9579A8;
  /* 角丸 */
  border-radius: 5px;
  /* 文字の大きさ */
  font-size: 20px;
  /* 文字の高さ */
  line-height: 1.5;
  position: relative;
  /* 対象にカーソルが触れた時の反応（矢印になる） */
  cursor: pointer;
}



/* アコーディオンのボタンとなる部分（三角形） */
.accordion-area .accordionHead:before {
  content: '';
  width: 0;
  height: 0;
  border-style: solid;
  /* 三角形の大きさ */
  border-width: 8.7px 5px 0 5px;
  /* 三角形の色 */
  border-color: #fff transparent transparent transparent;
  position: absolute;
  /* 三角形の縦位置（上基準） */
  top: 50%;
  /* 三角形の横位置（右基準） */
  right: 42px;
  /* 三角形の縦位置（topに「-」をつけた値 */
  transform: translateY(-50%);
  /* 表示順番 */
  z-index: 3;
}



/* アコーディオンのボタンとなる部分（三角形の背景） */
.accordion-area .accordionHead:after {
  content: '';
  /* 横幅 */
  width: 36px;
  /* 高さ */
  height: 36px;
  /* 背景色 */
  background: #78578E;
  /* 角丸 */
  border-radius: 5px;
  position: absolute;
  /* 縦位置（上基準） */
  top: 50%;
  /* 横位置（右基準） */
  right: 30px;
  /* 縦位置（topに「-」をつけた値 */
  transform: translateY(-50%);
  /* 表示順番 */
  z-index: 2;
}



/* コンテンツが入る外枠 */
.accordion-area .accordion-inner {
  /* 横幅（全体幅　 - 左右余白） */
  width: calc(100% - 100px);
  /*外側の余白｜上余白｜左右余白（auto=センタリング）｜下余白｜*/
  margin: -3px auto 30px;
  /*内側の余白｜上下余白｜左右余白｜*/
  padding: 30px 50px;
  /* 背景色 */
  background: #fff;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #9579A8;
  /* 初期、非表示 */
  display: none;
}



/* アコーディオンボタンをクリックした時 */
.accordion-area .accordion-inner.active {
  display: block;
}



/* コンテンツを格納している部分 */
.accordion-area .accordion-content {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  display: flex;
  /*水平方向に間隔を配置する方法。
  flex-start = 左側から配置する
  flex-end = 右側から配置する
  center = 真ん中に配置する
  space-around = 均等配置して両端に間隔を置く
  space-between = 均等配置してエリアの間に間隔を置く
  space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: flex-start;
  /*垂直方向にの配置位置を設定。
  center = 中央配置
  flex-start = 先頭にまとめる
  flex-end = 末尾にまとめる*/
  align-items: flex-start;
}



/* アコーディオン内画像部分 */
.accordion-area .accordion-imgBox {
  /* 横幅 */
  width: 40%;
  /* 高さ */
  height: auto;
  /* 外側の右余白 */
  margin-right: 5%;
}



/* 画像 */
.accordion-area .accordion-imgBox img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* アコーディオン内テキスト部分 */
.accordion-area .accordion-textBox {
  /* 横幅 */
  width: 55%;
  /* 高さ */
  height: auto;
}



/* テキスト */
.accordion-area .accordion-textBox .text {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 文字の大きさ */
  font-size: 18px;
  /* 色 */
  color: #000;
  /* 外側の余白 */
  margin: 0;
}

/* スマホ表示時（768以上でスマホ表示になります、数値は適宜変更してください） */
@media screen and (max-width: 768px) {


  /* コンテンツが入る箇所の設定 */
  .accordion-area .accordion-inner {
    /* 横幅（余白分を引いた値） */
    width: 90%;
    /*内側の余白｜上下余白｜左右余白｜*/
    padding: 30px 5%;
  }



  /* コンテンツを格納している部分 */
  .accordion-area .accordion-content {
    /* 折り返し設定 */
    flex-wrap: wrap;
  }



  /* アコーディオン内画像部分 */
  .accordion-area .accordion-imgBox {
    /* 横幅 */
    width: 100%;
    /* テキスト部分と隣接する余白 */
    margin-bottom: 10px;
    /* PC表示時に使っていたテキスト部分と隣接する余白 */
    margin-right: 0;
  }



  /* アコーディオン内テキスト部分 */
  .accordion-area .accordion-textBox {
    /* 横幅 */
    width: 100%;
  }
}

