.tbl-sticky {
  overflow-x: auto;
  max-width: 100%;
}

.tbl-sticky table {
  /* 表の横幅（記事幅を超える部分は横スクロール） */
  width: 800px;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0;
  border-top: 1px solid #ccc;
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
}

.tbl-sticky table th,
.tbl-sticky table td {
  vertical-align: middle;
  border: none;
  text-align: center;
  border-right: 1px solid #ccc;
  border-bottom: 1px solid #ccc;
  padding: 0.8em;
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
}

.tbl-sticky table th {
  /* 見出し幅 */
  width: 100px;
  position: -webkit-sticky;
  position: sticky;
  left: 0;
  z-index: 10;
  border-left: 1px solid #ccc;
  border-bottom: 1px solid #ccc;
  /* 左端見出しセルの色 */
  background-color: #f3f3f3;
}

.tbl-sticky table thead td {
  /* 王冠セルの色 */
  background-color: #f3f3f3;
}


.tbl-sticky ol,
.tbl-sticky ul {
  list-style-type: none;
  padding: 0;
  margin: 0;
  text-align: left;
}

.tbl-sticky ol>li p,
.tbl-sticky ul>li p {
  margin: 1em 0;
}

.tbl-sticky ol {
  counter-reset: item;
}

.tbl-sticky ol>li {
  text-indent: -1.3em;
  padding-left: 1.3em;
}

.tbl-sticky ol>li p {
  text-indent: 0;
}

.tbl-sticky ol>li::before {
  counter-increment: item;
  content: counter(item) ".";
  padding-right: 0.5em;
  font-weight: normal;
  margin: 0;
  text-align: left;
  display: inline;
  width: auto;
}

.tbl-sticky ul>li {
  text-indent: -1.3em;
  padding-left: 1.3em;
}

.tbl-sticky ul>li p {
  text-indent: 0;
}

.tbl-sticky ul>li::before {
  content: "\30fb";
  padding-right: 0.3em;
  font-weight: normal;
  margin: 0;
  text-align: left;
  display: inline;
  width: auto;
}

.tbl-sticky .btn {
  position: relative;
  display: block;
  padding: 1em;
  text-decoration: none;
  color: #fff;
  font-weight: 700;
  background-color: #f47118;
  border-bottom: solid 3px #ad5515;
  border-radius: 4px;
  -webkit-transition: all 0.2s;
  transition: all 0.2s;
}

.tbl-sticky .btn:hover {
  -webkit-transform: translateY(3px);
  transform: translateY(3px);
  -webkit-box-shadow: 0px 0px 1px rgba(0, 0, 0, 0.2);
  box-shadow: 0px 0px 1px rgba(0, 0, 0, 0.2);
  border-bottom: solid 1px #ad5515;
}

.tbl-sticky::-webkit-scrollbar {
  display: block;
  overflow: hidden;
  width: 6px;
  background: #eee;

  -webkit-border-radius: 3px;
  border-radius: 3px;
}

.tbl-sticky::-webkit-scrollbar:horizontal {
  height: 6px;
}

.tbl-sticky::-webkit-scrollbar-button {
  display: none;
}

.tbl-sticky::-webkit-scrollbar-piece {
  background: #eee;
}

.tbl-sticky::-webkit-scrollbar-piece:start {
  background: #eee;
}

.tbl-sticky::-webkit-scrollbar-thumb {
  overflow: hidden;
  -webkit-border-radius: 3px;
  border-radius: 3px;

  background: #666;
}

.tbl-sticky::-webkit-scrollbar-corner {
  overflow: hidden;
  -webkit-border-radius: 3px;
  border-radius: 3px;

  background: #666;
}

