/*全体*/
.table-of-contents {
  display: table;
  /*外側余白。上下｜左右（autoは真ん中寄せ）*/
  margin: 0 auto;
  /*横幅*/
  min-width: 100%;
  /*文字サイズ*/
  font-size: 0.9em;
  /*枠線。太さ｜種類｜色*/
  border: 1px dotted #333;
  /*角丸*/
  border-radius: 5px;
  /*内側余白*/
  padding: 10px;
  /*行の高さ*/
  line-height: 1.6;
  /*背景色*/
  background-color: #ffff99;
  box-sizing: border-box;
}



/*目次タイトル*/
.toc_title {
  /*周りの余白。上｜左右｜下*/
  margin: 0 0 10px;
  /*文字の水平方向の配置。左寄せはleft、真ん中はcenter*/
  text-align: center;
  /*文字サイズ*/
  font-size: 1.2em;
}



/*見出しリスト全体*/
.table-of-contents ul {
  /*周りの余白*/
  padding: 0;
  /*周りの余白*/
  margin: 5px 0;
  /*カウンター名*/
  counter-reset: section;
  list-style-type: none;
  list-style-image: none;
}



/*番号*/
.table-of-contents ul li::before {
  /*カウンターの値に1を追加*/
  counter-increment: section;
  /*見出しを入れ子にした場合は【.】を追加*/
  content: counters(section, ".") " ";
}



/*各リスト行*/
.table-of-contents li {
  /*余白。上｜右｜下｜左*/
  padding: 0 0 5px 10px;
}

.table-of-contents li::before {
  /*番号と文字の間余白*/
  padding-right: 8px;
}



/*目次リスト入れ子の場合*/
.table-of-contents ul ul {
  /*余白。上｜右｜下｜左*/
  margin: 0 0 0 10px;
}



/*各リスト文字の設定*/
.table-of-contents li::before,
.table-of-contents a {
  display: table-cell;
  /*文字色*/
  color: #000;
  /*要素の時間変化 1 = 1秒*/
  transition: 0.3s;
  /*リンクに下線をひく場合は下記削除*/
  text-decoration: none;
}



/*カーソルを乗せた時*/
.table-of-contents a:hover {
  /*文字色*/
  color: #0086ff !important;
}

.cp_actab {
  position: relative;
  overflow: hidden;
  width: 100%;
  margin: 0 auto;
  border: 1px solid #ccc;
  border-radius: 10px;
  color: #333;
}

.cp_actab input {
  position: absolute;
  z-index: -1;
  opacity: 0;
}

.cp_actab label {
  font-weight: bold;
  line-height: 3;
  position: relative;
  display: block;
  padding: 0 0 0 1em;
  cursor: pointer;
  margin: 0 0 1px 0;
  background: #ccc;
}

.cp_actab .cp_actab-content {
  overflow: hidden;
  max-height: 0;
  -webkit-transition: max-height 0.35s;
  transition: max-height 0.35s;
  color: #333;
  background: #fff;
  border-radius: 10px;

}

.cp_actab .cp_actab-content p {
  margin: 1em;
}

/* :checked */
.cp_actab input:checked~.cp_actab-content {
  max-height: 20em;
}

/* Icon */
.cp_actab label::after {
  line-height: 3;
  position: absolute;
  top: 0;
  right: 0;
  display: block;
  width: 3em;
  height: 3em;
  -webkit-transition: all 0.35s;
  transition: all 0.35s;
  text-align: center;
}

.cp_actab input[type=checkbox]+label::after {
  content: '+';
}

.cp_actab input[type=checkbox]:checked+label::after {
  transform: rotate(315deg);
}

